    function createCustomBasePlateModel(bpConfig) {

        if (!bpConfig) bpConfig = getDefaultBasePlateConfig();

        const model = { models: {}, paths: {} };

        

        if (bpConfig.plateShape === 'rect') {

            model.models.outer = new makerjs.models.Rectangle(parseFloat(bpConfig.width) || 6.0, parseFloat(bpConfig.height) || 6.0);

        } else if (bpConfig.plateShape === 'qiw_standard') {

            const w = bpConfig.qiwPlateType === 'QBP54' ? 5.0 : 4.0;

            const h = bpConfig.qiwPlateType === 'QBP54' ? 5.0 : 4.0;

            model.models.outer = new makerjs.models.Rectangle(w, h);

        } else {

            const pts = bpConfig.polyVerts.filter(v => v.x !== "" && v.y !== "").map(v => [parseFloat(v.x) || 0, parseFloat(v.y) || 0]);

            if (pts.length >= 3) {

                model.models.outer = { paths: {} };

                for (let i = 0; i < pts.length; i++) {

                    const p1 = pts[i];

                    const p2 = pts[(i + 1) % pts.length];

                    model.models.outer.paths['edge' + i] = new makerjs.paths.Line(p1, p2);

                }

            } else {

                model.models.outer = new makerjs.models.Rectangle(6.0, 6.0);

            }

        }

        

        model.models.holes = { models: {}, paths: {} };

        const holes = getCustomBasePlateHoleCoordinates(bpConfig);

        holes.forEach((h, idx) => {

            const origin = [h.x, h.y];

            const d = h.diameter;

            const r = d / 2;

            if (bpConfig.holeType === 'slotted' && (parseFloat(bpConfig.slotLength) || 1.0) > d) {

                const sl = parseFloat(bpConfig.slotLength) || 1.0;

                const sa = parseFloat(bpConfig.slotAngle) || 0;

                const slot = { paths: {} };

                const halfD = (sl - d) / 2;

                if (halfD > 0.01) {

                    slot.paths.line1 = new makerjs.paths.Line([-halfD, r], [halfD, r]);

                    slot.paths.line2 = new makerjs.paths.Line([-halfD, -r], [halfD, -r]);

                    slot.paths.cap1 = new makerjs.paths.Arc([halfD, 0], r, -90, 90);

                    slot.paths.cap2 = new makerjs.paths.Arc([-halfD, 0], r, 90, 270);

                } else {

                    slot.paths.circle = new makerjs.paths.Circle([0, 0], r);

                }

                makerjs.model.rotate(slot, sa, [0, 0]);

                slot.origin = origin;

                model.models.holes.models['hole_' + idx] = slot;

            } else {

                model.models.holes.paths['hole_' + idx] = new makerjs.paths.Circle(origin, r);

            }

        });

        

        return model;

    }



