                    const px = startPx + i * stepPx;

                    const ratio = (px - x0) / spanPx;

                    const topY = 376 * (1 - ratio) + (376 - deltaY) * ratio;

                    const botY = 712 * (1 - ratio) + (712 - deltaY) * ratio;

                    picketsSvg += `          <line x1="${px.toFixed(1)}" y1="${topY.toFixed(1)}" x2="${px.toFixed(1)}" y2="${botY.toFixed(1)}" stroke="#0f172a" stroke-width="5.5" />\n`;

