            vals.topRailType = (vals.topRailType && vals.topRailType !== 'none') ? vals.topRailType : 'hss_rect';





            vals.topRailSize = (vals.topRailSize && vals.topRailSize !== 'NONE' && vals.topRailSize !== 'none') ? vals.topRailSize : 'HSS1.5x1.5x14GA';





            vals.botRailType = (vals.botRailType && vals.botRailType !== 'none') ? vals.botRailType : 'hss_rect';





            vals.botRailSize = (vals.botRailSize && vals.botRailSize !== 'NONE' && vals.botRailSize !== 'none') ? vals.botRailSize : 'HSS1.5x1.5x14GA';





            vals.midRailType = (vals.fenceStyle === 'executive_custom') ? ((vals.midRailType && vals.midRailType !== 'none') ? vals.midRailType : 'hss_rect') : 'none';





