    // PDF Export Modal & Form Bindings





    const openExportModal = () => {





        if (currentMode === 'draft' && draftMembers.length === 0) {





            alert("Draft workspace is empty!");





            return;





        }





        const modal = document.getElementById('export-modal');





        if (modal) {





            modal.classList.remove('hidden');





            // Reset fields





            document.getElementById('exp-custom-finish-group').classList.add('hidden');





            document.getElementById('exp-finish').value = 'primer';





            document.getElementById('exp-customFinish').value = '';





            const drawingNoInput = document.getElementById('exp-drawingNo');





            const mainMarkInput = document.getElementById('exp-mainMark');





            if (drawingNoInput && mainMarkInput) {





                const updateMainMark = () => {





                    const rawNo = drawingNoInput.value.trim() || '55';





                    const cleanDrawingNo = rawNo.toUpperCase().replace(/[^A-Z0-9]/g, '') || '55';





                    mainMarkInput.value = cleanDrawingNo + 'M1';





                    const sidebarDrawing = document.getElementById('inp-drawingNo');





                    const sidebarMark = document.getElementById('inp-mainMark');





                    if (sidebarDrawing && document.activeElement === drawingNoInput) {





                        sidebarDrawing.value = drawingNoInput.value;





                    }





                    if (sidebarMark) {





                        sidebarMark.value = mainMarkInput.value;





                    }





                };





                drawingNoInput.removeEventListener('input', updateMainMark);





                drawingNoInput.addEventListener('input', updateMainMark);





                updateMainMark();





                mainMarkInput.readOnly = true;





            }





            // Add custom finish toggles





            const finishSelect = document.getElementById('exp-finish');





            const customFinishGroup = document.getElementById('exp-custom-finish-group');





            if (finishSelect && customFinishGroup) {





                const toggleFinish = () => {





                    if (finishSelect.value === 'custom') {





                        customFinishGroup.classList.remove('hidden');





                        document.getElementById('exp-customFinish').required = true;





                    } else {





                        customFinishGroup.classList.add('hidden');





                        document.getElementById('exp-customFinish').required = false;





                    }





                };





                finishSelect.removeEventListener('change', toggleFinish);





                finishSelect.addEventListener('change', toggleFinish);





            }





        }





    };





    // --- Drawing & Assembly Setup Sync Handlers ---





    const handleDrawingSetupSync = (source) => {





        const inpDrawing = document.getElementById('inp-drawingNo');





        const expDrawing = document.getElementById('exp-drawingNo');





        const inpQty = document.getElementById('inp-drawingQty');





        const expQty = document.getElementById('exp-qty');





        const inpMainMark = document.getElementById('inp-mainMark');





        const expMainMark = document.getElementById('exp-mainMark');





        let rawNo = '55';





        if (source === 'inp' && inpDrawing) {





            rawNo = inpDrawing.value;





            if (expDrawing) expDrawing.value = rawNo;





        } else if (source === 'exp' && expDrawing) {





            rawNo = expDrawing.value;





            if (inpDrawing) inpDrawing.value = rawNo;





        } else {





            rawNo = (inpDrawing?.value || expDrawing?.value || '55');





        }





        if (source === 'inp-qty' && inpQty && expQty) {





            expQty.value = inpQty.value;

            if (typeof window.syncLoosePostFromPanel === 'function') {

                window.syncLoosePostFromPanel();

            }





        } else if (source === 'exp-qty' && expQty && inpQty) {





            inpQty.value = expQty.value;

            if (typeof window.syncLoosePostFromPanel === 'function') {

                window.syncLoosePostFromPanel();

            }





        }





        const cleanNo = rawNo.trim().toUpperCase().replace(/[^A-Z0-9]/g, '') || '55';





        const mainMarkVal = cleanNo + 'M1';





        if (inpMainMark) inpMainMark.value = mainMarkVal;





        if (expMainMark) expMainMark.value = mainMarkVal;





        if (typeof updateBOMPreview === 'function') updateBOMPreview();





        if (typeof renderCurrentCAD === 'function' && currentMode === 'shapes') renderCurrentCAD();





        if (isLivePdfMode && typeof triggerLivePdfRefresh === 'function') triggerLivePdfRefresh();





    };





    ['inp-drawingNo', 'exp-drawingNo'].forEach(id => {





        const el = document.getElementById(id);





        if (el) {





            el.addEventListener('input', () => handleDrawingSetupSync(id.startsWith('inp') ? 'inp' : 'exp'));





            el.addEventListener('change', () => handleDrawingSetupSync(id.startsWith('inp') ? 'inp' : 'exp'));





        }





    });





    ['inp-drawingQty', 'exp-qty'].forEach(id => {





        const el = document.getElementById(id);





        if (el) {





            el.addEventListener('input', () => handleDrawingSetupSync(id.startsWith('inp') ? 'inp-qty' : 'exp-qty'));





            el.addEventListener('change', () => handleDrawingSetupSync(id.startsWith('inp') ? 'inp-qty' : 'exp-qty'));





        }





    });





