                        doc.setLineWidth(0.2);

                        doc.line(bottomPt[0], bottomPt[1], bottomPt[0], bottomPt[1] + extBelow);

                        const ty = bottomPt[1] + (extBelow / 2) + (textWidthMm / 2);

