                const botH = getProfileDimension(vals.botRailType || 'hss_rect', vals.botRailSize, vals.botRailH || 1.5);

                const picketW = getPicketDimension(vals.picketType || 'hss_rect', vals.picketSize, vals.picketW || 0.5);

