                const hasMidPosts = (!isGates && vals.midPosts && vals.midPosts !== 'none' && vals.midPosts !== 'no' && (vals.midPostCenters ? vals.midPostCenters.length > 0 : (parseInt(vals.midPostCount) || 0) > 0));

