                const panelTopY = fHeight;

                const panelBotY = hasPosts ? ((vals.botRailElevation !== undefined && vals.botRailElevation !== '' && !isNaN(parseFloat(vals.botRailElevation))) ? parseFloat(vals.botRailElevation) : 0) : 0;

                const yTop = (x) => panelTopY + x * tan;

                const yBot = (x) => panelBotY + x * tan;



                const isTrashGate = (vals.subCategory === 'trash_gate' || vals.subCategory === 'dumpster_gate');

                const hasPickets = (vals.picketType && vals.picketType !== 'none');



                const isSlopedFence = Math.abs(safeSlope) > 0.01;

