                    const heightFormatted = formatFraction(innerH);





                    const meshDesc = isWwm ? `WWM ${openingStr} * ${meshWire} * ${widthFormatted}` : `XF ${openVal}-${xfGaugeStr} X ${widthFormatted}`;





                    const meshRemark = isWwm ? "WWM MESH" : "EXPANDED METAL";





