                    const maxDeckLenInches = (parseFloat(vals.maxDeckLen) || 24.0) * 12.0;

                    const maxDeckWidthInches = parseFloat(vals.maxDeckWidth) || 36.0;

                    const fluteOrientation = vals.fluteOrientation || 'vertical';



