                    const spanDim = (fluteOrientation === 'horizontal') ? clearW : clearH;

                    const crossDim = (fluteOrientation === 'horizontal') ? clearH : clearW;



                    const qtyLength = Math.max(1, Math.ceil(spanDim / maxDeckLenInches));

                    const qtyWidth = Math.max(1, Math.ceil(crossDim / maxDeckWidthInches));

                    const deckQty = qtyLength * qtyWidth;



                    const pieceLen = spanDim / qtyLength;

                    const pieceWidth = crossDim / qtyWidth;

                    const widthFormatted = formatFraction(pieceWidth);



                    let sidingDesc = '';

                    let fbomDesc = '';

                    let shapeCode = 'MDG';

                    let deckGrade = deckType;

