                doc.setFont('helvetica', isBold ? 'bold' : 'normal');

                let currentSize = 6.8;

                doc.setFontSize(currentSize);

                let textW = doc.getTextWidth(text);

                const maxW = cellWidth - 1.8;

                while (textW > maxW && currentSize > 3.5) {

                    currentSize -= 0.1;

                    doc.setFontSize(currentSize);

                    textW = doc.getTextWidth(text);

                }

                let x = startX;

                if (alignment === "center") {

                    x = startX + cellWidth / 2;

                } else if (alignment === "left") {

                    x = startX + 1.2;

                } else if (alignment === "right") {

                    x = startX + cellWidth - 1.2;

                }

                doc.text(text, x, currentY + 4.8, { align: alignment });

                doc.setFontSize(6.8);

                doc.setFont('helvetica', 'normal');

