                const totalQty = isLoosePostItem ? item.qty : (typeof item.qty === 'number' ? (item.qty * assemblyQty) : item.qty);

                const totalWeight = isLoosePostItem ? item.weight : (typeof item.weight === 'number' ? (item.weight * assemblyQty) : item.weight);



