                        shapeCol = (item.shape === 'BY' || shapeCol === 'BY') ? 'BY' : 'PL';

                        if (shapeCol === 'PL') {

                            dimCol = dimCol.replace(/^PL(?:ATE)?\s*[-–]?\s*/i, '').replace(/\bPL\b\s*/gi, '').trim();

                            dimCol = dimCol.replace(/\s*[xX]\s*/g, ' X ').replace(/["']/g, '').trim();

                        }

